// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract RockPaperScissors {
    // Ходы: 0 = не выбран, 1 = камень, 2 = бумага, 3 = ножницы.
    enum Move {
        None,
        Rock,
        Paper,
        Scissors
    }

    // Этапы: 0 = commit, 1 = reveal, 2 = игра завершена.
    enum Phase {
        Commit,
        Reveal,
        Finished
    }

    // Результат: 0 = ожидается, 1 = ничья,
    // 2 = победил игрок 1, 3 = победил игрок 2.
    enum Result {
        Pending,
        Draw,
        Player1Wins,
        Player2Wins
    }

    struct Player {
        bytes32 commitment;
        Move move;
        bool committed;
        bool revealed;
    }

    address public immutable player1;
    address public immutable player2;

    mapping(address => Player) public players;

    Phase public phase;
    Result public result;
    address public winner;

    event MoveCommitted(address indexed player, bytes32 commitment);
    event RevealPhaseStarted();
    event MoveRevealed(address indexed player, Move move);
    event GameFinished(Result result, address indexed winner);

    modifier onlyPlayer() {
        require(
            msg.sender == player1 || msg.sender == player2,
            "You are not a player"
        );
        _;
    }

    // Создатель контракта становится игроком 1.
    // Адрес игрока 2 передаётся при развёртывании.
    constructor(address opponent) {
        require(opponent != address(0), "Invalid opponent");
        require(opponent != msg.sender, "Players must be different");

        player1 = msg.sender;
        player2 = opponent;

        phase = Phase.Commit;
        result = Result.Pending;
    }

    // Вспомогательная функция вычисления хеша.
    // В учебном Remix VM вызываем её кнопкой чтения.
    function getCommitment(
        address player,
        Move move,
        string memory salt
    ) public view returns (bytes32) {
        require(
            player == player1 || player == player2,
            "Invalid player"
        );
        require(move != Move.None, "Invalid move");
        require(bytes(salt).length > 0, "Salt is required");

        return keccak256(
            abi.encode(
                address(this),
                block.chainid,
                player,
                move,
                salt
            )
        );
    }

    // Этап 1: игрок отправляет только хеш.
    function commit(bytes32 commitment) external onlyPlayer {
        require(phase == Phase.Commit, "Not commit phase");

        Player storage currentPlayer = players[msg.sender];

        require(!currentPlayer.committed, "Already committed");
        require(commitment != bytes32(0), "Empty commitment");

        currentPlayer.commitment = commitment;
        currentPlayer.committed = true;

        emit MoveCommitted(msg.sender, commitment);

        // Раскрытие разрешается только после обоих commit.
        if (players[player1].committed && players[player2].committed) {
            phase = Phase.Reveal;
            emit RevealPhaseStarted();
        }
    }

    // Этап 2: игрок раскрывает ход и соль.
    function reveal(
        Move move,
        string calldata salt
    ) external onlyPlayer {
        require(phase == Phase.Reveal, "Not reveal phase");

        Player storage currentPlayer = players[msg.sender];

        require(!currentPlayer.revealed, "Already revealed");

        bytes32 calculatedHash = getCommitment(
            msg.sender,
            move,
            salt
        );

        require(
            calculatedHash == currentPlayer.commitment,
            "Move or salt does not match"
        );

        currentPlayer.move = move;
        currentPlayer.revealed = true;

        emit MoveRevealed(msg.sender, move);

        // После второго раскрытия результат определяется автоматически.
        if (players[player1].revealed && players[player2].revealed) {
            _finishGame();
        }
    }

    // Проверяет, побеждает ли первый переданный ход второй.
    function _beats(Move first, Move second)
        private
        pure
        returns (bool)
    {
        return
            (first == Move.Rock && second == Move.Scissors) ||
            (first == Move.Paper && second == Move.Rock) ||
            (first == Move.Scissors && second == Move.Paper);
    }

    // Этап 3: определение результата.
    function _finishGame() private {
        Move firstMove = players[player1].move;
        Move secondMove = players[player2].move;

        phase = Phase.Finished;

        if (firstMove == secondMove) {
            result = Result.Draw;
            winner = address(0);
        } else if (_beats(firstMove, secondMove)) {
            result = Result.Player1Wins;
            winner = player1;
        } else {
            result = Result.Player2Wins;
            winner = player2;
        }

        emit GameFinished(result, winner);
    }
}

